import java.util.*;
import java.io.*;

public class Main {
    static int[] countLakes(String[] grid, int[][] queries) {
        // grid[i].charAt(j) is '1' for land and '0' for water; return one answer per query
        // Write your solution here
        return new int[queries.length];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int r = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        String[] grid = new String[r];
        for (int i = 0; i < r; i++) grid[i] = br.readLine().trim();
        int q = Integer.parseInt(br.readLine().trim());
        int[][] queries = new int[q][2];
        for (int i = 0; i < q; i++) {
            st = new StringTokenizer(br.readLine());
            queries[i][0] = Integer.parseInt(st.nextToken());
            queries[i][1] = Integer.parseInt(st.nextToken());
        }
        int[] res = countLakes(grid, queries);
        StringBuilder sb = new StringBuilder();
        for (int x : res) sb.append(x).append("\n");
        System.out.print(sb);
    }
}

